import React, { useEffect, useState } from 'react'
import PropertiesTable from './PropertiesTable'
import useApi from '../../../hooks/useApi'
import { useNavigate } from 'react-router-dom';
import PropertyFormModal from './PropertyFormModal';
import propertiesApi from '../../../api/properties/propertiesApi';
import { Loading } from '../../../components';

const columns = [

    { name: "Title", uid: "title" },
    { name: "County", uid: "county_title" },
    { name: "Town", uid: "town" },
    { name: "Street Address", uid: "street_address" },
    { name: "For", uid: "disposal_type" },
    { name: "Type", uid: "property_type" },
    { name: "Number", uid: "property_number" },
    { name: "Units", uid: "number_of_units" },
    { name: "Monthly Revenue", uid: "monthly_revenue" },
    { name: "Actions", uid: "actions" },
];


function PropertiesList() {
    const [openEditModal, setopenEditModal] = useState(false)
    const [modalTitle, setmodalTitle] = useState("")
    const navigate = useNavigate()
    const [property, setProperty] = useState()

    const [data, setdata] = useState([])
    const [updated, setUpdated] = useState(false)


    const [properties, setProperties] = useState([])
    const propertiesActionsApi = useApi(propertiesApi.propertiesAction)

    const getProperties = async () => {
        await propertiesActionsApi.request({
            "action": "GetEntityProperties"

        })
    }


    useEffect(() => {
        getProperties()
    }, [])

    
    useEffect(() => {
      if (propertiesActionsApi.data && propertiesActionsApi.data.length) {
        setProperties(propertiesActionsApi.data);
      }

      console.log("propertiesActionsApi.data", propertiesActionsApi.data);
    }, [propertiesActionsApi.data]);

    useEffect(() => {
      getProperties();
    }, [updated]);


    const handleEditAction = (item) => {
      console.log("to edit ", item);
      setUpdated(false);
      setopenEditModal(true);
      setProperty(item);
      setmodalTitle(`${item.title}`);
    };

    const handleAddAction = () => {
      setUpdated(false);
      setopenEditModal(true);
      setmodalTitle("Add new property");
      setProperty(null);
    };
    const handleDetailsAction = (property) => {
      navigate(`/realty/properties/details`, {
        state: {
          property: property,
        },
      });
    };
    const handleDeleteAction = (property) => {
      navigate(`/realty/properties/delete/${property.id}`);
    };


    //Filtering data
    useEffect(() => {
      setdata(properties);
    }, [properties]);

    const handleFilter = (e) => {
      const search_param = e;

      if (
        properties &&
        properties.length > 0 &&
        search_param &&
        search_param !== ""
      ) {
        setdata(
          properties.filter((x) => x.title.toLowerCase().includes(search_param))
        );
      } else {
        setdata(properties);
      }
    };

    return (
      <div>
        {openEditModal && (
          <PropertyFormModal
            ismodalOpen={openEditModal}
            setisModalOpen={setopenEditModal}
            propertyToEdit={property}
            updated={updated}
            setUpdated={setUpdated}
            modalTitle={modalTitle}
          />
        )}
        {propertiesActionsApi.loading ? (
          <Loading loading={propertiesActionsApi.loading} />
        ) : (
          <PropertiesTable
            data={data}
            columns={columns}
            editAction={handleEditAction}
            detailsAction={handleDetailsAction}
            deleteAction={handleDeleteAction}
            addAction={handleAddAction}
            handleFilter={handleFilter}
            title={"Properties"}
          />
        )}
      </div>
    );
}

export default PropertiesList